package com.citacloud.springboot.contacloud.app.models;
import jakarta.persistence.*;import java.math.BigDecimal;import java.time.OffsetDateTime;import java.util.UUID;
@Entity @Table(name="supplier_payment_application") public class AplicacionPagoProveedor{
 @Id @GeneratedValue(strategy=GenerationType.UUID)private UUID id;@Column(name="tenant_id",nullable=false)private UUID tenantId;@Column(name="empresa_id",nullable=false)private UUID empresaId;@Column(name="supplier_payment_id",nullable=false)private UUID pagoId;@Column(name="purchase_invoice_id",nullable=false)private UUID facturaId;@Column(name="accounts_payable_id",nullable=false)private UUID cuentaPagarId;@Column(nullable=false,precision=19,scale=4)private BigDecimal amount;@Column(name="previous_balance",nullable=false,precision=19,scale=4)private BigDecimal saldoAnterior;@Column(name="remaining_balance",nullable=false,precision=19,scale=4)private BigDecimal saldoRestante;@Column(name="applied_at",nullable=false,insertable=false,updatable=false)private OffsetDateTime aplicadaEn;@Column(name="applied_by",nullable=false)private UUID aplicadaPor;@Column(nullable=false)private boolean reversed;@Column(name="reversed_at")private OffsetDateTime revertidaEn;@Column(name="reversed_by")private UUID revertidaPor;@Column(name="reversal_reason",length=500)private String motivoReversion;
 protected AplicacionPagoProveedor(){}public AplicacionPagoProveedor(UUID t,UUID e,UUID p,UUID f,UUID c,BigDecimal m,BigDecimal anterior,BigDecimal restante,UUID u){tenantId=t;empresaId=e;pagoId=p;facturaId=f;cuentaPagarId=c;amount=m;saldoAnterior=anterior;saldoRestante=restante;aplicadaPor=u;}public void revertir(String motivo,UUID usuario){reversed=true;revertidaEn=OffsetDateTime.now();revertidaPor=usuario;motivoReversion=motivo;}public UUID getId(){return id;}public UUID getPagoId(){return pagoId;}public UUID getFacturaId(){return facturaId;}public UUID getCuentaPagarId(){return cuentaPagarId;}public BigDecimal getMonto(){return amount;}public BigDecimal getSaldoAnterior(){return saldoAnterior;}public BigDecimal getSaldoRestante(){return saldoRestante;}public OffsetDateTime getAplicadaEn(){return aplicadaEn;}public UUID getAplicadaPor(){return aplicadaPor;}public boolean isRevertida(){return reversed;}
}
